/bin/bash -lc "python - <<'PY'
from qutebrowser.utils.utils import parse_duration
for value in ('5s', '2m30s', '1h', '90', '1.5h', '0.25m', '1h 2m 3s'):
    print(value, parse_duration(value))
for value in ('', '   ', '-1s', '1x', '1s2m'):
    try:
        parse_duration(value)
    except ValueError:
        print(repr(value), 'rejected')
    else:
        raise AssertionError(value)
PY
git diff --check && git diff -- qutebrowser/utils/utils.py qutebrowser/misc/utilcmds.py"

